<script setup lang="ts">
import type {AutomaticRetryPolicy} from '@/api/automatic-retry';
const props=defineProps<{modelValue?:AutomaticRetryPolicy|null;disabled?:boolean}>();
const emit=defineEmits<{(e:'update:modelValue',value:AutomaticRetryPolicy|null):void}>();
function toggle(enabled:boolean){if(props.disabled)return;emit('update:modelValue',enabled?{schemaVersion:'iqc-automatic-retry-v1',maximumAttempts:3,initialDelaySeconds:60,multiplier:2,maximumDelaySeconds:3600,effectiveUntil:null}:null);}
function change(key:keyof AutomaticRetryPolicy,value:unknown){if(props.disabled||!props.modelValue)return;emit('update:modelValue',{...props.modelValue,[key]:value});}
</script>
<template><section><a-form-item label="自动重试（默认关闭）"><a-switch :checked="!!modelValue" :disabled="disabled" @change="(value: unknown)=>toggle(!!value)"/></a-form-item><a-alert type="info" message="最大次数包括初次及手动重试，自动重试不会重置上限；沿用已冻结的数据和版本。"/><template v-if="modelValue"><a-form-item label="最多执行次数（1–10）"><a-input-number :value="modelValue.maximumAttempts" :min="1" :max="10" :disabled="disabled" @change="(value: unknown)=>change('maximumAttempts',value)"/></a-form-item><a-form-item label="初始延迟秒数（1–86400）"><a-input-number :value="modelValue.initialDelaySeconds" :min="1" :max="86400" :disabled="disabled" @change="(value: unknown)=>change('initialDelaySeconds',value)"/></a-form-item><a-form-item label="退避倍率（整数1–4）"><a-input-number :value="modelValue.multiplier" :precision="0" :min="1" :max="4" :disabled="disabled" @change="(value: unknown)=>change('multiplier',value)"/></a-form-item><a-form-item label="最大延迟秒数（不少于初始延迟，最多604800）"><a-input-number :value="modelValue.maximumDelaySeconds" :min="modelValue.initialDelaySeconds" :max="604800" :disabled="disabled" @change="(value: unknown)=>change('maximumDelaySeconds',value)"/></a-form-item><a-form-item label="截止时间（可选 ISO，含时区）"><a-input :value="modelValue.effectiveUntil??''" :disabled="disabled" @update:value="(value: unknown)=>change('effectiveUntil',value||null)"/></a-form-item></template></section></template>
